using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Text.RegularExpressions;
namespace RelayLite {
internal static class NativeTests {
    static void Assert(bool value,string name){if(!value)throw J.Error(name);}
    public static void Run(){string root=Path.Combine(Program.BaseDir,"self-test-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);var checks=new List<string>();try{CompatibilityTests.Run(checks,root);var secure=new Secure();string key="sk-fake-native-test-only";Assert(secure.Decrypt(secure.Encrypt(key))==key,"DPAPI round trip");checks.Add("DPAPI encryption");string config=Path.Combine(root,"fake-codex");Directory.CreateDirectory(config);string original="# keep comment\nmodel = \"gpt-test\"\nmodel_reasoning_effort = \"high\"\n[features]\nkeep = true\n";File.WriteAllText(Path.Combine(config,"config.toml"),original);var store=new Store(Path.Combine(root,"store"),config,secure);var a=store.Upsert(J.Map("name","测试中转","baseUrl","https://fixture.example/v1","siteUrl","https://fixture.example","key",key,"accountKey","fake-account-token","model","gpt-test","adapter","auto"));string id=J.Str(a,"id");Assert(J.Str(store.Details(id),"key")==key,"saved key refill");Assert(!J.Encode(store.List()).Contains(key),"public list hides key");Assert(!File.ReadAllText(store.File).Contains(key),"file encrypted");checks.Add("provider CRUD and masked fields");store.Switch(id);string written=File.ReadAllText(Path.Combine(config,"config.toml"));Assert(written.Contains("# keep comment")&&written.Contains("keep = true")&&written.Contains("experimental_bearer_token"),"safe switch preserves config");string backup=J.Str(J.Arr(J.Get(store.List(),"history"))[0],"id");store.Restore(backup);Assert(File.ReadAllText(Path.Combine(config,"config.toml"))==original,"exact restore");checks.Add("config switch and exact restore");var quotedConfig=Path.Combine(root,"quoted-codex");Directory.CreateDirectory(quotedConfig);File.WriteAllText(Path.Combine(quotedConfig,"config.toml"),"model_provider = \"Relay Custom\"\n[model_providers.\"Relay Custom\"]\nname = \"Custom\"\nbase_url = \"https://custom.example/v1\"\n");var quotedStore=new Store(Path.Combine(root,"quoted-store"),quotedConfig,new Secure());var quoteInfo=quotedStore.ConfigInfo();if(J.Str(quoteInfo,"baseUrl")!="https://custom.example/v1")throw J.Error("quoted TOML table key: "+J.Encode(quoteInfo));checks.Add("full TOML parser and quoted provider names");string redundant=Path.Combine(root,"redundant-parent");Directory.CreateDirectory(redundant);string redundantOriginal="model_provider = \"custom\"\n[model_providers.custom]\nname = \"Custom\"\nbase_url = \"https://custom.example/v1\"\n[features]\nkeep = true\n[model_providers]\n\n[projects.example]\ntrust_level = \"trusted\"\n";File.WriteAllText(Path.Combine(redundant,"config.toml"),redundantOriginal);var redundantStore=new Store(Path.Combine(root,"redundant-store"),redundant,secure);Assert(J.Str(redundantStore.ConfigInfo(),"baseUrl")=="https://custom.example/v1","empty redundant parent table parses");var c=redundantStore.Upsert(J.Map("name","normalized","baseUrl","https://normalized.example/v1","siteUrl","https://normalized.example","key","fake-key-three"));string redundantId=J.Str(c,"id");var firstSwitch=J.Obj(redundantStore.Switch(redundantId));Assert(J.True(J.Get(J.Arr(J.Get(firstSwitch,"providers")).Select(J.Obj).First(x=>J.Str(x,"id")==redundantId),"active")),"first relay marked active");var d=redundantStore.Upsert(J.Map("name","second","baseUrl","https://second.example/v1","siteUrl","https://second.example","key","fake-key-four"));string secondId=J.Str(d,"id");var secondSwitch=J.Obj(redundantStore.Switch(secondId));Assert(J.True(J.Get(J.Arr(J.Get(secondSwitch,"providers")).Select(J.Obj).First(x=>J.Str(x,"id")==secondId),"active"))&&!J.True(J.Get(J.Arr(J.Get(secondSwitch,"providers")).Select(J.Obj).First(x=>J.Str(x,"id")==redundantId),"active")),"relay switching updates active state");string normalized=File.ReadAllText(Path.Combine(redundant,"config.toml"));Assert(!Regex.IsMatch(normalized,@"(?m)^\s*\[\s*model_providers\s*\]\s*$")&&normalized.Contains("[model_providers.custom]")&&normalized.Contains("https://second.example"),"redundant parent removed on switch");var redundantHistory=J.Arr(J.Get(secondSwitch,"history")).Select(J.Obj).ToList();redundantStore.Restore(J.Str(redundantHistory[0],"id"));redundantStore.Restore(J.Str(redundantHistory[1],"id"));Assert(File.ReadAllText(Path.Combine(redundant,"config.toml"))==redundantOriginal,"redundant table backup restores exactly");checks.Add("relay switching, empty parent normalization and exact restore");var b=store.Upsert(J.Map("name","second","baseUrl","https://second.example/v1","siteUrl","https://second.example","key","fake-key-two"));store.Reorder(new[]{J.Str(b,"id"),id});Assert(J.Str(J.Arr(J.Get(store.List(),"providers"))[0],"id")==J.Str(b,"id"),"order persisted");checks.Add("sort order");J.Atomic(Path.Combine(Program.BaseDir,"self-test-result.json"),J.Encode(J.Map("ok",true,"checks",checks)));}catch(Exception ex){J.Atomic(Path.Combine(Program.BaseDir,"self-test-result.json"),J.Encode(J.Map("ok",false,"checks",checks,"error",ex.ToString())));Environment.ExitCode=1;}}
}
}
